	{
		unsigned v = 0x3f800000;
		*(unsigned *)&m_a = v;
		*(unsigned *)&m_b = v;
		*(unsigned *)&m_c = v;
		*(unsigned *)&m_d = v;
		*(unsigned *)&m_e = v;
		*(unsigned *)&m_f = v;
